UPDATE posts
SET status = status + 1
WHERE post_id = #{postId}
  AND status = #{status}
  AND version = #{version}

UPDATE posts
SET version = version + 1,
    status = 2
WHERE post_id = #{postId}
  AND version = #{version}

mapper.select:
SELECT version, status
FROM posts
WHERE post_id = #{postId}
